import{_ as s,o as a,c as t,af as n}from"./chunks/framework.BSym9njW.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"00-environment/lemonade.md","filePath":"en/00-environment/lemonade.md","lastUpdated":1789547203000}'),l={name:"00-environment/lemonade.md"};function i(d,e,o,r,p,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h2 id="lemonade-environment-ubuntu-24-04" tabindex="-1">Lemonade environment (Ubuntu 24.04) <a class="header-anchor" href="#lemonade-environment-ubuntu-24-04" aria-label="Permalink to &quot;Lemonade environment (Ubuntu 24.04)&quot;">​</a></h2><p>This page installs <a href="https://github.com/lemonade-sdk/lemonade" target="_blank" rel="noreferrer">Lemonade Server</a> on Ubuntu 24.04: OpenAI-compatible API plus Web UI. GPU uses llama.cpp; NPU uses FastFlowLM. Model pull lives in <a href="/hello-rocm/01-deploy/">01-Deploy</a>.</p><blockquote><p>Official docs: <a href="https://lemonade-server.ai/docs/guide/install/ubuntu/" target="_blank" rel="noreferrer">Ubuntu install</a> · <a href="https://lemonade-server.ai/flm_npu_linux.html" target="_blank" rel="noreferrer">Linux NPU / FLM</a></p><p>Driver and IOMMU details: <a href="./fastflowlm">FastFlowLM environment</a>. Lemonade only calls an already-installed <code>flm</code>.</p></blockquote><hr><h3 id="validated-baseline-2026-09-16" tabindex="-1">Validated baseline (2026-09-16) <a class="header-anchor" href="#validated-baseline-2026-09-16" aria-label="Permalink to &quot;Validated baseline (2026-09-16)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Item</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;">Package</td><td style="text-align:left;"><code>lemonade-server</code> <strong>11.9.0~24.04</strong></td></tr><tr><td style="text-align:left;">CLI</td><td style="text-align:left;"><code>lemonade version 11.9.0</code></td></tr><tr><td style="text-align:left;">Server</td><td style="text-align:left;"><code>/usr/bin/lemond</code>, default <strong>13305</strong></td></tr><tr><td style="text-align:left;">OpenAI</td><td style="text-align:left;"><code>http://127.0.0.1:13305/api/v1</code> (some clients also try <code>/v1</code>)</td></tr><tr><td style="text-align:left;">GPU backend</td><td style="text-align:left;"><strong><code>llamacpp:vulkan</code></strong> (on kernel 6.17, <code>llamacpp:rocm</code> reported <em>Linux kernel missing support</em>)</td></tr><tr><td style="text-align:left;">NPU backend</td><td style="text-align:left;">this tutorial recommends <strong>native FastFlowLM on 8219</strong> (see below)</td></tr><tr><td style="text-align:left;">systemd</td><td style="text-align:left;"><code>lemond.service</code>, working directory <code>/var/lib/lemonade</code></td></tr></tbody></table><hr><h3 id="_1-install-the-server" tabindex="-1">1. Install the server <a class="header-anchor" href="#_1-install-the-server" aria-label="Permalink to &quot;1. Install the server&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> add-apt-repository</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -y</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ppa:lemonade-team/stable</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> apt</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> update</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> apt</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> install</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -y</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> lemonade-server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --version</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>You should see <code>lemonade version 11.9.0</code> (or newer). When the server is up: <code>Server is running on port 13305</code>. Open <code>http://127.0.0.1:13305</code>.</p><p>APT usually enables <strong><code>lemond.service</code></strong> (user <code>lemonade</code>, <code>ProtectHome=yes</code>). To stop:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> systemctl</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> stop</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> lemond</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> systemctl</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> disable</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --now</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> lemond</span><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">   # optional: no autostart</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>⚠️ The unit name is <strong><code>lemond</code></strong>, not <code>lemonade-server</code>.</p></blockquote><hr><h3 id="_2-install-inference-backends" tabindex="-1">2. Install inference backends <a class="header-anchor" href="#_2-install-inference-backends" aria-label="Permalink to &quot;2. Install inference backends&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> backends</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> backends</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> install</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> llamacpp:vulkan</span><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">   # skip if already installed</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> backends</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>llamacpp:rocm</code> needs a kernel that meets <a href="https://lemonade-server.ai/gfx1151_linux.html" target="_blank" rel="noreferrer">gfx1151 Linux</a>. Otherwise use Vulkan.</p><p><strong>About <code>flm:npu</code>:</strong></p><ul><li><code>lemonade backends install flm:npu</code> downloads FLM from GitHub and often times out in mainland China.</li><li>Even with a system <code>flm</code>, <code>lemond.service</code> runs as <code>lemonade</code> with <strong>ProtectHome=yes</strong>, so it <strong>cannot read</strong> <code>~/.config/flm</code>.</li><li>This tutorial therefore runs NPU via <a href="./fastflowlm">FastFlowLM</a> + <code>flm serve</code> on <strong>8219</strong>.</li><li>If you run <code>lemond</code> in the foreground as your login user (no ProtectHome) and successfully install <code>flm:npu</code>, you can try <code>lemonade load &lt;flm-tag&gt;</code>.</li></ul><p>Do not <code>source /opt/rocm</code> on Lemonade’s NPU path.</p><hr><h3 id="_3-health-check" tabindex="-1">3. Health check <a class="header-anchor" href="#_3-health-check" aria-label="Permalink to &quot;3. Health check&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --version</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> status</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> backends</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ss</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -tlnp</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> | </span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">grep</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 13305</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Optional: <code>bash src/npu/scripts/check_lemonade.sh</code>. For NPU also run <code>bash src/npu/scripts/check_flm_npu.sh</code> after unsetting ROCm paths.</p><hr><h3 id="_4-common-commands" tabindex="-1">4. Common commands <a class="header-anchor" href="#_4-common-commands" aria-label="Permalink to &quot;4. Common commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><code>lemonade backends</code></td><td style="text-align:left;">installed / available backends</td></tr><tr><td style="text-align:left;"><code>lemonade status</code></td><td style="text-align:left;">server on 13305, loaded model</td></tr><tr><td style="text-align:left;"><code>lemonade list</code></td><td style="text-align:left;">catalog; <code>--downloaded</code> for local only</td></tr><tr><td style="text-align:left;"><code>lemonade pull NAME</code></td><td style="text-align:left;">download (<code>--source modelscope</code> in China)</td></tr><tr><td style="text-align:left;"><code>lemonade load NAME</code></td><td style="text-align:left;">load into the server</td></tr><tr><td style="text-align:left;"><code>lemonade unload</code></td><td style="text-align:left;">unload</td></tr><tr><td style="text-align:left;"><code>lemonade run NAME</code></td><td style="text-align:left;">load + open Web UI</td></tr><tr><td style="text-align:left;"><code>lemonade chat</code></td><td style="text-align:left;">terminal REPL</td></tr></tbody></table><p>GPU backend pin:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> load</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> Gemma-4-E4B-it-GGUF</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --llamacpp</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> vulkan</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><h3 id="_5-ports-in-this-tutorial" tabindex="-1">5. Ports in this tutorial <a class="header-anchor" href="#_5-ports-in-this-tutorial" aria-label="Permalink to &quot;5. Ports in this tutorial&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Port</th><th style="text-align:left;">Use</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>13305</strong></td><td style="text-align:left;">Lemonade Server</td></tr><tr><td style="text-align:left;"><strong>8219</strong></td><td style="text-align:left;">native <code>flm serve</code> (<strong>exclusive</strong> with Lemonade NPU)</td></tr></tbody></table><p>Next: <a href="/hello-rocm/01-deploy/gemma4/lemonade-gpu-deploy">Gemma 4 Lemonade GPU</a> · <a href="/hello-rocm/01-deploy/gemma4/lemonade-npu-deploy">Gemma 4 Lemonade NPU</a> · <a href="./npu-troubleshooting">NPU troubleshooting</a></p>`,34)])])}const m=s(l,[["render",i]]);export{k as __pageData,m as default};
